[CmdletBinding()]
param(
    [switch]$SkipBrowserInstall,
    [switch]$SkipQualityGate,
    [switch]$SkipSmoke
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$ExpectedBase = "2f76180a78372598ecbd0ffcdcea02bb651dc081"
$RepoRoot = Split-Path -Parent $PSScriptRoot
Set-Location $RepoRoot

$PermanentPaths = @(
    ".github/workflows/ci.yml",
    "apps/api/Endpoints/Editorial/TranslationRevisionAdministrationEndpoints.cs",
    "apps/web/src/routes/editorial/TranslationEditor.tsx",
    "apps/web/src/routes/editorial/TranslationStructurePage.tsx",
    "apps/web/src/routes/editorial/translation-structure.css",
    "apps/web/src/routes/editorial/translation-editor.css",
    "docs/engineering/content/translation-editor.md",
    "scripts/apply-bl-mvp-062.ps1",
    "scripts/ci/content/verify-translation-editor.sh",
    "src/Modules/Content/Infrastructure/Administration/TranslationRevisionAdministrationService.cs",
    "tests/E2ETests/translation-revision-model.spec.ts",
    "tests/E2ETests/translation-editor.spec.ts"
)

function Assert-LastExitCode([string]$Step) {
    if ($LASTEXITCODE -ne 0) {
        throw "$Step fallo con codigo de salida $LASTEXITCODE."
    }
}

function Decode-Utf8Base64([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString(
        [System.Convert]::FromBase64String($Value))
}

function Read-Normalized([string]$RelativePath) {
    $path = Join-Path $RepoRoot $RelativePath
    if (-not (Test-Path $path -PathType Leaf)) {
        throw "Falta $RelativePath."
    }

    return ([System.IO.File]::ReadAllText(
        $path,
        [System.Text.Encoding]::UTF8)).Replace("`r`n", "`n").Replace("`r", "`n")
}

function Write-Utf8NoBomLf([string]$RelativePath, [string]$Content) {
    $path = Join-Path $RepoRoot $RelativePath
    $directory = Split-Path -Parent $path
    if ($directory -and -not (Test-Path $directory -PathType Container)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }

    [System.IO.File]::WriteAllText(
        $path,
        $Content.Replace("`r`n", "`n").Replace("`r", "`n"),
        [System.Text.UTF8Encoding]::new($false))
}

function Replace-ExactOnce(
    [string]$RelativePath,
    [string]$OldText,
    [string]$NewText,
    [string]$AlreadyMarker,
    [string]$Description) {

    $content = Read-Normalized $RelativePath

    if ($content.Contains($AlreadyMarker)) {
        Write-Host "OK: $Description ya estaba aplicado."
        return
    }

    $first = $content.IndexOf($OldText, [System.StringComparison]::Ordinal)
    if ($first -lt 0) {
        throw "No se encontro el bloque esperado para $Description en $RelativePath."
    }

    $second = $content.IndexOf(
        $OldText,
        $first + $OldText.Length,
        [System.StringComparison]::Ordinal)

    if ($second -ge 0) {
        throw "El bloque de $Description aparece mas de una vez en $RelativePath."
    }

    $updated = $content.Remove($first, $OldText.Length).Insert($first, $NewText)
    Write-Utf8NoBomLf $RelativePath $updated
    Write-Host "OK: $Description aplicado."
}

function Restore-GeneratedTypeScriptState {
    $relativePath = "apps/web/tsconfig.app.tsbuildinfo"
    git ls-files --error-unmatch -- $relativePath *> $null
    if ($LASTEXITCODE -ne 0) {
        $global:LASTEXITCODE = 0
        return
    }

    $status = git status --porcelain=v1 -- $relativePath
    if ($status) {
        git restore --worktree -- $relativePath
        Assert-LastExitCode "Restaurar tsbuildinfo"
        Write-Host "Restaurado $relativePath por ser salida incremental rastreada."
    }
}

function Get-ChangedPaths {
    $tracked = @(git diff --name-only)
    Assert-LastExitCode "Leer cambios tracked"
    $untracked = @(git ls-files --others --exclude-standard)
    Assert-LastExitCode "Leer cambios untracked"

    return @(
        $tracked + $untracked |
            Where-Object { $_ } |
            Sort-Object -Unique
    )
}

function Assert-InventorySubset {
    $allowed = @{}
    foreach ($path in $PermanentPaths) {
        $allowed[$path] = $true
    }

    foreach ($path in Get-ChangedPaths) {
        if (-not $allowed.ContainsKey($path)) {
            throw "Ruta fuera del inventario BL-MVP-062: $path"
        }
    }
}

function Resolve-GitBash {
    foreach ($candidate in @(
        "C:\Program Files\Git\bin\bash.exe",
        "C:\Program Files\Git\usr\bin\bash.exe"
    )) {
        if (Test-Path $candidate -PathType Leaf) {
            return $candidate
        }
    }

    $bashCommand = Get-Command bash.exe -ErrorAction SilentlyContinue
    if ($null -ne $bashCommand) {
        return $bashCommand.Source
    }

    throw "No se encontro Git Bash real."
}

Write-Host "BL-MVP-062 v8: snapshot completo de traducción + protección anti-pérdida..."

$head = (git rev-parse HEAD).Trim()
Assert-LastExitCode "Leer HEAD"
if ($head -cne $ExpectedBase) {
    throw "BL-MVP-062 requiere HEAD exacto $ExpectedBase y encontro $head."
}

$branch = (git branch --show-current).Trim()
Assert-LastExitCode "Leer rama"
if ($branch -cne "main") {
    throw "BL-MVP-062 debe instalarse desde main."
}

$staged = @(git diff --cached --name-only)
Assert-LastExitCode "Revisar staging"
if ($staged.Count -gt 0) {
    throw "BL-MVP-062 requiere staging vacio."
}

Restore-GeneratedTypeScriptState
Assert-InventorySubset

$initialChanges = @(Get-ChangedPaths)
if ($initialChanges.Count -gt 0) {
    Write-Host "OK: reanudacion BL062 detectada; los cambios existentes pertenecen al inventario permitido."
}

foreach ($required in @(
    ".github/workflows/ci.yml",
    "apps/api/Endpoints/Editorial/TranslationRevisionAdministrationEndpoints.cs",
    "apps/web/src/routes/editorial/TranslationStructurePage.tsx",
    "src/Modules/Content/Infrastructure/Administration/TranslationRevisionAdministrationService.cs"
)) {
    if (-not (Test-Path $required -PathType Leaf)) {
        throw "Falta archivo base requerido: $required"
    }
}

Write-Utf8NoBomLf `
    "src/Modules/Content/Infrastructure/Administration/TranslationRevisionAdministrationService.cs" `
    (Decode-Utf8Base64 "")
Write-Host "OK: servicio M04 editable."

Write-Utf8NoBomLf `
    "apps/api/Endpoints/Editorial/TranslationRevisionAdministrationEndpoints.cs" `
    (Decode-Utf8Base64 "")
Write-Host "OK: endpoint GET/POST de traduccion."

Write-Utf8NoBomLf `
    "apps/web/src/routes/editorial/TranslationStructurePage.tsx" `
    (Decode-Utf8Base64 "")
Write-Host "OK: UI-MVP-023 integra editor."

Write-Utf8NoBomLf `
    "apps/web/src/routes/editorial/translation-structure.css" `
    (Decode-Utf8Base64 "")
Write-Host "OK: estructura completa de traduccion reorganizada."

Write-Utf8NoBomLf `
    "apps/web/src/routes/editorial/TranslationEditor.tsx" `
    (Decode-Utf8Base64 "")
Write-Host "OK: editor de traduccion."

Write-Utf8NoBomLf `
    "apps/web/src/routes/editorial/translation-editor.css" `
    (Decode-Utf8Base64 "")
Write-Host "OK: estilos responsivos del editor."

Write-Utf8NoBomLf `
    "docs/engineering/content/translation-editor.md" `
    (Decode-Utf8Base64 "")
Write-Host "OK: documentacion de ingenieria BL062."

Write-Utf8NoBomLf `
    "scripts/ci/content/verify-translation-editor.sh" `
    (Decode-Utf8Base64 "")
Write-Host "OK: verificador CI BL062."

Write-Utf8NoBomLf `
    "tests/E2ETests/translation-revision-model.spec.ts" `
    (Decode-Utf8Base64 "")
Write-Host "OK: selectores BL061 adaptados a coexistencia read-only + editor."

Write-Utf8NoBomLf `
    "tests/E2ETests/translation-editor.spec.ts" `
    (Decode-Utf8Base64 "")
Write-Host "OK: Playwright BL062."

Replace-ExactOnce `
    ".github/workflows/ci.yml" `
    (Decode-Utf8Base64 "") `
    (Decode-Utf8Base64 "") `
    "Verify Spanish translation editor" `
    "puerta CI BL-MVP-062"

Assert-InventorySubset

$formatTargets = @(
    ".github/workflows/ci.yml",
    "apps/web/src/routes/editorial/TranslationStructurePage.tsx",
    "apps/web/src/routes/editorial/TranslationEditor.tsx",
    "apps/web/src/routes/editorial/translation-structure.css",
    "apps/web/src/routes/editorial/translation-editor.css",
    "docs/engineering/content/translation-editor.md",
    "tests/E2ETests/translation-revision-model.spec.ts",
    "tests/E2ETests/translation-editor.spec.ts"
)

Write-Host "Aplicando Prettier a superficies BL062..."
npx.cmd prettier --write @formatTargets
Assert-LastExitCode "Prettier BL062"

Write-Host "Verificando formato global..."
npm.cmd run format:check
Assert-LastExitCode "Formatting check global"

$bash = Resolve-GitBash
& $bash -n "scripts/ci/content/verify-translation-editor.sh"
Assert-LastExitCode "bash -n BL062"

if (-not $SkipBrowserInstall) {
    npm.cmd run test:e2e:install
    Assert-LastExitCode "Instalar Chromium Playwright"
}

Write-Host "Compilando frontend antes del Playwright focal..."
npm.cmd run build --workspace @musica-aprender/web
Assert-LastExitCode "Build frontend focal BL062"

Write-Host "Ejecutando Playwright focal BL061 + BL062..."
npm.cmd run test:e2e -- `
    tests/E2ETests/translation-revision-model.spec.ts `
    tests/E2ETests/translation-editor.spec.ts
Assert-LastExitCode "Playwright focal BL062"

Restore-GeneratedTypeScriptState

if (-not $SkipQualityGate) {
    Write-Host "Ejecutando puerta completa de calidad..."
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$RepoRoot/scripts/check-quality.ps1"
    Assert-LastExitCode "Quality gate BL062"
}

Write-Host "Compilando Release para BL-MVP-062..."
dotnet build MusicaAprender.sln --configuration Release --no-restore
Assert-LastExitCode "Build Release BL062"

if (-not $SkipSmoke) {
    Write-Host "Preparando PostgreSQL local para smoke BL-MVP-062..."
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$RepoRoot/scripts/local/ensure-local-secrets.ps1"
    Assert-LastExitCode "Secret store local BL062"
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$RepoRoot/scripts/local/sync-postgres-secret.ps1"
    Assert-LastExitCode "Sincronizar secreto PostgreSQL BL062"
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$RepoRoot/scripts/database/apply-bootstrap.ps1"
    Assert-LastExitCode "Bootstrap PostgreSQL BL062"
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$RepoRoot/scripts/database/apply-login-identities.ps1"
    Assert-LastExitCode "LOGIN identities BL062"
    powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$RepoRoot/scripts/database/apply-initial-migration.ps1"
    Assert-LastExitCode "Migracion inicial BL062"

    $database = "musica_aprender"
    $databaseUser = "musica_local"

    if (Test-Path ".env") {
        foreach ($line in Get-Content ".env") {
            if ($line -match '^POSTGRES_DB=(.+)$') {
                $database = $Matches[1].Trim()
            }
            if ($line -match '^POSTGRES_USER=(.+)$') {
                $databaseUser = $Matches[1].Trim()
            }
        }
    }

    $previousEnv = @{
        PGHOST = $env:PGHOST
        PGPORT = $env:PGPORT
        PGUSER = $env:PGUSER
        PGPASSWORD = $env:PGPASSWORD
        PGDATABASE = $env:PGDATABASE
        BL062_USE_DOCKER_PSQL = $env:BL062_USE_DOCKER_PSQL
    }

    try {
        $env:PGHOST = "127.0.0.1"
        $env:PGPORT = "5432"
        $env:PGUSER = $databaseUser
        $env:PGPASSWORD = "unused-docker-exec"
        $env:PGDATABASE = $database
        $env:BL062_USE_DOCKER_PSQL = "true"

        & $bash "scripts/ci/content/verify-translation-editor.sh"
        Assert-LastExitCode "Smoke BL-MVP-062"
    }
    finally {
        foreach ($name in $previousEnv.Keys) {
            $value = $previousEnv[$name]
            if ($null -eq $value) {
                Remove-Item "Env:$name" -ErrorAction SilentlyContinue
            }
            else {
                Set-Item "Env:$name" $value
            }
        }
    }
}

Restore-GeneratedTypeScriptState
Assert-InventorySubset

git diff --check
Assert-LastExitCode "git diff --check BL062"

$changed = @(Get-ChangedPaths)
$expected = @($PermanentPaths | Sort-Object -Unique)

if ($changed.Count -ne $expected.Count) {
    throw "BL-MVP-062 esperaba $($expected.Count) rutas y encontro $($changed.Count)."
}

for ($index = 0; $index -lt $expected.Count; $index++) {
    if ($changed[$index] -cne $expected[$index]) {
        throw "Inventario BL-MVP-062 no coincide. Esperado '$($expected[$index])', encontrado '$($changed[$index])'."
    }
}

Write-Host ""
Write-Host "OK: inventario final exacto de $($expected.Count) rutas BL-MVP-062."
Write-Host ""
git status --short --untracked-files=all
Write-Host ""
git diff --stat
Write-Host ""
git diff --name-status
Write-Host ""
Write-Host "OK: BL-MVP-062 instalado y validado localmente."
Write-Host "Edita literal/natural y notas sobre revision japonesa exacta con ETag, CSRF y procedencia."
Write-Host "No modifica japones, no publica y no usa APIs de traduccion externas."
Write-Host "PENDIENTE: reinicio normal y revision visual real de UI-MVP-023 antes de staging."
Write-Host "No se ejecuto git add, commit ni push."
